providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "One short diagnostic on simple series circuits: correctly compute total resistance, current and each resistor's voltage drop for a changed circuit, or explain the exact step that failed so a small follow-up can be booked."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I usually solve simple series circuits correctly; give only a short diagnostic if useful. Do not certify mastery from confidence.",
          "explanation": "The learner reports usually solving simple series circuits correctly, but there is no owned demonstrated-readiness evidence, so CREDITED is not available. A single short integrated diagnostic is the smallest useful work: it checks the core series relations (current equal everywhere, resistances add, voltage drops sum to source voltage) on changed numbers, and it can simultaneously serve as explanation if a step breaks down. No separate relearning, repeated practice set or second check is booked now, because the accepted outcome explicitly asks for only a short diagnostic if useful and confidence cannot certify mastery. Further remediation stays contingent on a concrete observed failure at that checkpoint.",
          "recommendedEffort": {
            "lowMinutes": 15,
            "likelyMinutes": 25,
            "highMinutes": 35
          },
          "phases": [
            {
              "localId": "diagnose",
              "title": "Short series-circuit diagnostic",
              "outcome": "A clean, evidence-based read on whether the learner can solve changed simple series circuits unaided.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 25,
                "highMinutes": 35
              },
              "readinessCriterion": "Correctly computes total resistance, current and each resistor's voltage drop for a changed simple series circuit, with the series rules stated during the work; or identifies the exact failed step so a bounded follow-up can be triggered."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Diagnostic coverage of simple series circuits: series rules, total resistance, current and voltage drops on changed values."
          }
        ],
        "activities": [
          {
            "localId": "series_diagnostic",
            "outcomeRefs": [
              "diagnose"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Changed-value series circuit diagnostic",
            "activityType": "Integrated diagnostic and explanation",
            "purpose": "Provide owned evidence of unaided simple-series-circuit solving, or pinpoint the exact failed step, without a separate relearning or repeated practice set.",
            "instructions": "Solve one changed simple series circuit with a DC source and three resistors in series, using values you have not seen before. (1) State the series rules you are using: current is the same through every component, resistances add, and the voltage drops sum to the source voltage. (2) Compute the total resistance. (3) Compute the current. (4) Compute the voltage drop across each resistor and verify the drops sum to the source voltage. (5) If any step fails, write the exact step and what went wrong instead of guessing. Do not use worked examples or answer keys during the attempt.",
            "completionCriterion": "Either all computed values (total resistance, current, each voltage drop, and the sum check) are correct with the series rules stated, or the exact failed step is identified with a concrete reason.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 25,
              "highMinutes": 35
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "series_remediation",
            "outcomeRefs": [
              "diagnose"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Bounded remediation on the failed series step",
            "activityType": "Targeted explanation and corrected re-attempt",
            "purpose": "Repair only the specific failed step exposed by the diagnostic, then re-check that step on a changed value.",
            "instructions": "Based on the diagnostic result, explain the exact rule or step that failed (for example, adding resistances, applying I = V/R, or summing voltage drops). Then solve one changed simple series circuit that exercises that same step, and verify the result with the series rules. Do not repeat already-correct steps as a full set.",
            "completionCriterion": "The previously failed step is explained correctly and the changed circuit is solved correctly with the series rules stated.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 25,
              "highMinutes": 35
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "series_diagnostic",
                "condition": "The diagnostic shows an incorrect total resistance, current, voltage drop, or sum check, or an inability to state the series rules."
              }
            },
            "hardDependencies": [
              "series_diagnostic"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has access to basic DC series-circuit formulas (Ohm's law and series resistance addition) from prior study."
          ],
          "tradeOffs": [
            "No separate relearning or repeated practice set is booked because the accepted outcome asks only for a short diagnostic if useful and there is no observed failure yet.",
            "The diagnostic doubles as explanation if a step fails, avoiding a second check of already verified items."
          ],
          "unresolvedUncertainty": [
            "Whether the learner can solve changed simple series circuits unaided is unknown until the diagnostic is completed."
          ],
          "stoppingConditions": [
            "Stop after the diagnostic if all computed values and the series rules are correct.",
            "If the diagnostic fails, stop after the bounded remediation once the failed step is explained and one changed circuit is solved correctly."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The accepted outcome explicitly asks for only a short diagnostic if useful, and there is no owned demonstrated-readiness evidence to credit. I therefore booked one integrated diagnostic that can also explain a failed step, and left any further remediation contingent on a concrete observed failure rather than adding a separate relearning, repeated practice set or second check. This avoids certifying mastery from confidence and avoids silently extending the assignment."
}

