{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can pick and justify the right circuit method (Ohm's law, series/parallel, KCL/KVL, or a taught simplification) on changed circuits and solve them correctly without help."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "The learner can select the correct circuit method on unfamiliar circuits and apply it accurately, moving beyond the current pattern of choosing the wrong law.",
          "explanation": "The stated weakness is method selection, not voltage/current concepts, so the work targets choice and justification on changed circuits rather than relearning basic definitions. A single integrated activity lets the learner see worked method-selection reasoning, then immediately apply it to a changed circuit with an independent check; this is enough to test the capability without padding. No separate practice set or second check is committed because no observed failure exists yet.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "select_apply",
              "title": "Select and apply circuit methods",
              "outcome": "Correct method choice, valid selection reason, and correct solution on changed course-appropriate circuits without assistance.",
              "readinessCriterion": "The learner independently solves a changed circuit using the chosen method and gives a valid reason for the choice, with no help."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The integrated activity directly addresses method selection on circuits, which is the stated weakness."
          }
        ],
        "activities": [
          {
            "localId": "method_selection",
            "outcomeRefs": [
              "select_apply"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Choose and apply the right circuit method on changed circuits",
            "activityType": "guided method-selection practice with independent changed example",
            "purpose": "Build and verify the ability to select the correct law or method on unfamiliar circuits and apply it correctly.",
            "instructions": "1) Review one worked example that shows how to choose between Ohm's law, series/parallel rules, KCL/KVL, and any taught simplification, with the reason for each choice. 2) For each of two changed circuits, first write one sentence naming the method you will use and why, then solve for the requested voltage or current, showing your steps. 3) Check each result by an independent route (for example, verify KVL around a loop or confirm power balance). 4) If a choice or result is wrong, correct it and state what signal in the circuit you missed.",
            "completionCriterion": "On two changed circuits, you correctly name and justify the method, solve for the requested quantity, and verify each result by an independent check.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner already understands voltage and current conceptually, as stated.",
            "The taught repertoire includes Ohm's law, series/parallel rules, and KCL/KVL at minimum."
          ],
          "tradeOffs": [
            "No separate conceptual reteach is committed because the stated weakness is selection, not understanding.",
            "No timed exam simulation is committed because no deadline or assessment format is given."
          ],
          "unresolvedUncertainty": [
            "The exact set of methods in the course is not specified beyond the stated examples."
          ],
          "stoppingConditions": [
            "Stop after the committed activity once the completion criterion is met; no further practice is required unless the check reveals a failed selection."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "A single integrated method-selection activity is enough to address the stated weakness without adding redundant practice. No separate conceptual relearning is committed because voltage and current understanding is reported as adequate. No timed paper practice is committed because no deadline or assessment format is provided."
}

