providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can look at an unfamiliar circuit, state which law or method applies and why, then apply it correctly and check the result — with no assistance."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I can explain voltage and current but choose the wrong law on unfamiliar circuits. Focus on selecting and applying the method.",
          "explanation": "The reported weakness is method selection, not conceptual understanding of voltage and current, which the learner can already explain. So the work targets the decision step: given an unfamiliar circuit, justify which law or method applies and then apply it correctly. One integrated session combines a short decision rule, supported application, and a changed independent example, which is enough to establish the capability without redundant relearning or multiple practice sets. A single contingent extension handles a concrete observed failure rather than assuming one will occur.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "select_apply",
              "title": "Selecting and applying circuit methods",
              "outcome": "Choose the correct law or method on unfamiliar circuits, state a valid selection reason, and solve correctly without assistance.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 45,
                "highMinutes": 60
              },
              "readinessCriterion": "On at least two changed, course-appropriate circuits, correctly name the applicable law or method, give a valid reason for the choice, and reach the correct solution unaided."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The whole target capability: selecting the right law or method on unfamiliar circuits and applying it correctly."
          }
        ],
        "activities": [
          {
            "localId": "method_selection",
            "outcomeRefs": [
              "select_apply"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Deciding and applying the right circuit method on unfamiliar circuits",
            "activityType": "Guided method-selection practice",
            "purpose": "Turn the learner's existing voltage/current understanding into correct method choice and correct application on unfamiliar circuits.",
            "instructions": "1) Write a short decision rule for yourself: for a given circuit, list the cues that tell you whether to use Ohm's law, series/parallel combination, Kirchhoff's laws, or another method already taught in your course. 2) Work one supported example: read the circuit, state which method applies and why, then apply it step by step, checking units and signs. 3) Then take two changed, unfamiliar circuits (different topology and different given/unknown quantities from the supported example) and for each: name the method, give your selection reason, solve it, and verify the result (e.g. by an independent check such as power balance or a second route). Do not look up the method choice; write your reasoning first, then check.",
            "completionCriterion": "For two changed unfamiliar circuits, you name the correct law or method, give a valid selection reason, and reach the correct solution with your own verification, with no assistance.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 25,
                "completionCriterion": "Decision rule written and the supported example solved correctly with an explicit method-choice reason."
              }
            ]
          },
          {
            "localId": "method_remediation",
            "outcomeRefs": [
              "select_apply"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted remediation on the observed method-selection failure",
            "activityType": "Failure-triggered remediation",
            "purpose": "Repair the specific method-selection error observed in the committed activity, without repeating already verified work.",
            "instructions": "Take only the circuit(s) where your method choice was wrong in the committed activity. Re-examine the cues you missed, rewrite the relevant part of your decision rule, then solve one fresh circuit of the same type and confirm the corrected choice and solution.",
            "completionCriterion": "On one fresh circuit of the previously failed type, you name the correct method, give a valid reason, and solve correctly unaided.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 25,
              "highMinutes": 40
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "method_selection",
                "condition": "In the committed activity, at least one changed circuit was solved with the wrong law or method despite a correct final numeric answer, or the stated selection reason was invalid."
              }
            },
            "hardDependencies": [
              "method_selection"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner's course has already taught the relevant circuit laws and methods (Ohm's law, series/parallel, Kirchhoff's laws) so no new method is introduced here."
          ],
          "tradeOffs": [
            "No separate conceptual relearning of voltage and current is booked, because the learner can already explain them; effort is concentrated on the reported selection weakness.",
            "A second full practice set and a separate check of already verified items are omitted as redundant; only a concrete observed failure triggers extra work."
          ],
          "unresolvedUncertainty": [
            "The exact repertoire of methods taught in the course is not specified; the activity assumes standard introductory methods and the learner should substitute the course's own taught methods if different."
          ],
          "stoppingConditions": [
            "Stop once two changed unfamiliar circuits are solved with correct method choice, valid reasons, and correct verified solutions unaided.",
            "If the committed activity already meets this, do not book the contingent remediation."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "Because the weakness is method selection rather than conceptual understanding, the plan skips separate relearning of voltage and current and any redundant second practice set. It commits one integrated session that requires a method choice with a valid reason plus a correct verified solution on changed circuits — the exact evidence needed to show the capability. Further remediation is left contingent on a concrete observed method-selection failure, so no extra work is scheduled unless the evidence demands it."
}

