{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can explain Bayes' rule in your own words, apply it correctly to a changed medical-test example with a different prevalence, and identify which quantities are base rate versus sensitivity, with no reliance on notes."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "Develop the ability to explain Bayes’ rule and apply it to a changed medical-test probability example. I confuse the base rate with sensitivity.",
          "explanation": "The core weakness is a specific confusion: the learner conflates the base rate (prevalence) with sensitivity. This is a conceptual mapping error, not a computational one, so the plan first builds an explicit distinction between the four quantities (prevalence, sensitivity, false positive rate, and the posterior), then integrates explanation, supported application, and an independent changed example in a single compact activity. No prior readiness evidence exists, so a brief diagnostic is embedded in the first activity rather than a separate relearning set. Remediation is contingent on a concrete observed failure at the committed checkpoint.",
          "recommendedEffort": {
            "lowMinutes": 40,
            "likelyMinutes": 60,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "phase_distinguish",
              "title": "Distinguish base rate from sensitivity",
              "outcome": "Correctly label prevalence, sensitivity, false positive rate, and posterior in a worked medical-test scenario.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 20,
                "highMinutes": 30
              },
              "readinessCriterion": "You correctly assign all four quantities in a fresh scenario without notes."
            },
            {
              "localId": "phase_apply",
              "title": "Apply Bayes' rule to a changed example",
              "outcome": "Compute the posterior probability for a medical-test example with a different prevalence and explain each term in the formula.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 40,
                "highMinutes": 60
              },
              "readinessCriterion": "You produce the correct posterior and a valid term-by-term explanation on a changed example without assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Provides the conceptual foundation: prevalence (base rate), sensitivity, specificity, and false positive rate must be distinguished before Bayes' rule is applied."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The central tool: Bayes' rule is explained and then applied, with each term mapped to its medical-test meaning."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Transfers the skill to an unfamiliar example with changed parameters, testing whether the base-rate/sensitivity distinction holds without notes."
          }
        ],
        "activities": [
          {
            "localId": "distinguish_and_apply",
            "outcomeRefs": [
              "phase_distinguish",
              "phase_apply"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Explain Bayes' rule and solve a changed medical-test example",
            "activityType": "Integrated explanation and applied problem solving",
            "purpose": "Build the base-rate/sensitivity distinction and immediately apply it to a changed example so the confusion is corrected through use, not repetition.",
            "instructions": "1) Write down, in your own words, the difference between the base rate (prevalence) and sensitivity in a medical test. 2) State Bayes' rule for a positive test result and label each term (prevalence, sensitivity, false positive rate). 3) Work through this example: a disease has prevalence 1 in 1000; the test has sensitivity 99% and false positive rate 5%. Compute the probability that a person who tests positive actually has the disease. Show the numerator and denominator separately. 4) Then change the prevalence to 1 in 50 and recompute. 5) Explain in one or two sentences why the posterior changed and which quantity drove the change. If any step is unclear, explain the step you are stuck on before moving on.",
            "completionCriterion": "You produce correct posteriors for both prevalence values (approximately 1.94% for 1 in 1000 and approximately 28.8% for 1 in 50), correctly label prevalence versus sensitivity in your explanation, and give a valid reason for why the posterior changed.",
            "effort": {
              "lowMinutes": 40,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "remediation_base_rate",
            "outcomeRefs": [
              "phase_distinguish"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Targeted remediation: rebuild the base-rate versus sensitivity mapping",
            "activityType": "Contingent focused explanation and practice",
            "purpose": "Address a concrete observed failure in distinguishing base rate from sensitivity with a focused re-explanation and a small contrasting pair of examples.",
            "instructions": "Re-read your work from the integrated activity and identify the exact step where you swapped base rate and sensitivity. Then: 1) Write the two quantities side by side with a one-line definition each. 2) Take one example where prevalence is very low and one where it is high, keeping sensitivity fixed, and compute the posterior for each. 3) State in one sentence how the posterior moved and which input caused it. Do not re-solve the original examples unless you cannot identify the error.",
            "completionCriterion": "You correctly define both quantities, compute both posteriors correctly, and correctly attribute the change in posterior to prevalence rather than sensitivity.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "distinguish_and_apply",
                "condition": "You swap or mislabel the base rate and sensitivity in your written explanation, or your posterior calculation uses sensitivity where prevalence belongs."
              }
            },
            "hardDependencies": [
              "distinguish_and_apply"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has basic familiarity with fractions and percentages but no prior formal study of Bayes' rule."
          ],
          "tradeOffs": [
            "A single integrated activity is preferred over separate explanation, practice, and check stages because the weakness is conceptual and best corrected through immediate application.",
            "No separate diagnostic is scheduled because the integrated activity itself reveals the base-rate/sensitivity confusion."
          ],
          "unresolvedUncertainty": [
            "Whether the learner can transfer the distinction to a non-medical context is untested and outside the accepted outcome."
          ],
          "stoppingConditions": [
            "Stop when the learner correctly explains Bayes' rule and solves the changed medical-test example without notes.",
            "Do not add further practice sets unless the contingent remediation is triggered by an observed failure."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan uses one integrated committed activity rather than separate explanation, practice, and check stages because the reported weakness is a specific conceptual confusion (base rate versus sensitivity) that is best corrected by explaining the distinction and immediately applying it to a changed example. Remediation is contingent on an observed failure at that checkpoint, so no additional practice is booked unless the learner actually swaps the quantities. This keeps the plan small and bounded while still meeting the mastery outcome."
}

