{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You have worked through the actual five changed circuits you got wrong, explained the correct method choice and solution for each, and then correctly solved one fresh changed circuit with a valid selection reason, unaided."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "I say I have mastered circuit methods, but in my self-reported last check I got four of five changed circuits wrong. Do not ignore this contradiction or certify mastery from my claim; choose proportionate education and a meaningful check.",
          "explanation": "The self-report of mastery is contradicted by the reported 4/5 failure on changed circuits, and there is no completed-work history to credit. Proportionate education therefore means diagnosing the actual errors on those five circuits, reworking each with explicit method-choice reasoning, and verifying capability on one fresh changed circuit. A single integrated rework-and-verify activity is sufficient; further practice is only warranted if the fresh circuit fails.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 75,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "rework",
              "title": "Rework the failed changed circuits",
              "outcome": "Each of the five changed circuits is solved correctly with an explicit, valid method-selection reason.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 50,
                "highMinutes": 75
              },
              "readinessCriterion": "You can explain why each chosen method applies to that circuit and produce the correct result."
            },
            {
              "localId": "verify",
              "title": "Verify on a fresh changed circuit",
              "outcome": "One new changed circuit is solved correctly, unaided, with a valid method-selection reason.",
              "effort": {
                "lowMinutes": 15,
                "likelyMinutes": 25,
                "highMinutes": 45
              },
              "readinessCriterion": "Correct method choice, valid selection reason and correct solution on a changed circuit without assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The rework and fresh-circuit verification directly address independent circuit method selection, the exact capability the self-report contradicts."
          }
        ],
        "activities": [
          {
            "localId": "rework_circuits",
            "outcomeRefs": [
              "rework"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Rework the five changed circuits you got wrong",
            "activityType": "Guided error analysis and re-solve",
            "purpose": "Diagnose the actual errors and rebuild correct method selection on the specific circuits that failed.",
            "instructions": "Retrieve the five changed circuits from your last check. For each one: (1) state which method you chose and why it applies to that circuit's structure; (2) solve it step by step, showing the governing equations or rules; (3) check your result against the circuit's expected behavior (units, limiting cases, or a second method where feasible); (4) if your original answer was wrong, write the specific misconception or slip that caused it and the corrected reasoning. Work through all five; do not skip the one you got right, but spend most time on the four failures.",
            "completionCriterion": "All five circuits have a correct solution, an explicit valid method-selection reason, and a written correction for any original error.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 50,
              "highMinutes": 75
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "fresh_circuit",
            "outcomeRefs": [
              "verify"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Solve one fresh changed circuit unaided",
            "activityType": "Independent transfer check",
            "purpose": "Provide the meaningful check of whether method selection now works on a changed circuit without help.",
            "instructions": "Choose or obtain one changed circuit you have not solved before, at the same level as the previous check. Without notes or assistance, state which method you are choosing and the reason it applies, then solve it fully. Afterward, compare your result with the correct answer or a second valid method and record whether your method choice and solution were correct.",
            "completionCriterion": "Correct method choice, valid selection reason and correct solution on the fresh changed circuit without assistance.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 25,
              "highMinutes": 45
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "rework_circuits"
            ]
          },
          {
            "localId": "remediation",
            "outcomeRefs": [
              "verify"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted remediation on the fresh-circuit failure",
            "activityType": "Failure-triggered remediation",
            "purpose": "Address a concrete observed failure on the fresh circuit with focused re-teaching and re-check.",
            "instructions": "If the fresh circuit check fails, identify the specific method-selection or solution error. Re-study the relevant rule or method, rework that circuit correctly with explanation, then attempt one further changed circuit of the same type and verify method choice and solution.",
            "completionCriterion": "The specific error is corrected and one further changed circuit is solved correctly with a valid method-selection reason.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 35,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "fresh_circuit",
                "condition": "The fresh changed circuit is solved incorrectly or the method-selection reason is invalid."
              }
            },
            "hardDependencies": [
              "fresh_circuit"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The five changed circuits from the last check are available to rework.",
            "The taught repertoire covers the methods needed for these circuits."
          ],
          "tradeOffs": [
            "No separate broad relearning set is booked because the reported failure is best addressed on the actual failed circuits plus one fresh transfer check."
          ],
          "unresolvedUncertainty": [
            "The exact nature of the four errors is unknown until the rework is done; remediation is therefore contingent on the fresh-circuit result."
          ],
          "stoppingConditions": [
            "Stop after the fresh circuit is solved correctly with a valid method-selection reason; do not add further practice unless the contingent remediation triggers."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan prioritizes correcting the actual four failed circuits over generic review, and uses one fresh changed circuit as the meaningful check. Further practice is only added if that check fails, avoiding unnecessary work while honoring the mastery policy and the contradiction between the self-report and the observed failure."
}

